import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"MiniMax Code tutorial","description":"Install the desktop app from the download page. The official CLI command is mcode. Copy only official install text.","frontmatter":{"title":"MiniMax Code tutorial","description":"Install the desktop app from the download page. The official CLI command is mcode. Copy only official install text.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/minimax-code/minimax-code.md","filePath":"products/minimax-code/minimax-code.md","lastUpdated":1787107158000}'),o={name:"products/minimax-code/minimax-code.md"};function n(r,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="minimax-code-tutorial" tabindex="-1">MiniMax Code tutorial <a class="header-anchor" href="#minimax-code-tutorial" aria-label="Permalink to &quot;MiniMax Code tutorial&quot;">​</a></h1><blockquote><p>This page goes from install to the first local-repo task. Flags live in the <a href="./minimax-code-cheatsheet.html">cheatsheet</a>, recipes in the <a href="./minimax-code-cookbook.html">cookbook</a>, and names in the <a href="./minimax-code-glossary.html">glossary</a>.</p><p>MiniMax Code has a desktop face and a CLI face. Official text: it &quot;complements the desktop client&quot; (<a href="https://agent.minimax.io/docs/cli/features" target="_blank" rel="noreferrer">CLI Features</a>). Install one face first.</p></blockquote><h2 id="_1-pick-a-face" tabindex="-1">1. Pick a face <a class="header-anchor" href="#_1-pick-a-face" aria-label="Permalink to &quot;1. Pick a face&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where you work</th><th>Install</th><th>Official entry</th></tr></thead><tbody><tr><td>Window, browser preview, schedules, phone remote</td><td>Desktop</td><td><a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">International download</a> / <a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">CN download</a></td></tr><tr><td>Terminal, scripts, CI, editor ACP</td><td>CLI (<code>mcode</code>)</td><td><a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI Quick Start</a></td></tr></tbody></table><p>You can install both. They are one product.</p><h2 id="_2-install-the-desktop-app" tabindex="-1">2. Install the desktop app <a class="header-anchor" href="#_2-install-the-desktop-app" aria-label="Permalink to &quot;2. Install the desktop app&quot;">​</a></h2><p>From <a href="https://agent.minimax.io/docs/code/get-started/download" target="_blank" rel="noreferrer">Download and Install</a>:</p><blockquote><p>MiniMax Code supports macOS and Windows. After installation, sign in with your MiniMax account to start creating tasks.</p></blockquote><table tabindex="0"><thead><tr><th>Platform</th><th>Requirement</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 11 Big Sur or later</td></tr><tr><td>Windows</td><td>Windows 10 or later</td></tr></tbody></table><p>Official steps (same page):</p><ol><li>Open the download page and pick the package for your device. <strong>Use arm64 for Apple silicon Macs and x64 for Intel Macs.</strong></li><li>On macOS, open the <code>.dmg</code> and drag the app into Applications. On Windows, run the installer.</li><li>Launch MiniMax Code and sign in with your MiniMax account.</li><li>The app notifies you about updates. You can also check from settings.</li></ol><p>International build: <a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">agent.minimax.io/download</a>. Mainland China build: <a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">agent.minimaxi.com/download</a>.</p><p>The desktop app has <strong>no</strong> official one-line <code>curl</code> installer. Do not use the CLI script in the next section to install the GUI.</p><h2 id="_3-install-the-cli" tabindex="-1">3. Install the CLI <a class="header-anchor" href="#_3-install-the-cli" aria-label="Permalink to &quot;3. Install the CLI&quot;">​</a></h2><p>From <a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI Quick Start</a>:</p><blockquote><p>The installer reuses a compatible Node.js installation when available. If your system does not have a compatible version, it installs a self-contained runtime in your user directory. The entire process requires neither <code>sudo</code> nor administrator privileges.</p></blockquote><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-OtBKN" id="tab-aT7ZBGb" checked><label data-title="macOS / Linux / WSL" for="tab-aT7ZBGb">macOS / Linux / WSL</label><input type="radio" name="group-OtBKN" id="tab-KmBGCn2"><label data-title="Windows PowerShell" for="tab-KmBGCn2">Windows PowerShell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://filecdn.minimax.chat/public/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filecdn.minimax.chat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></div></div><p>Then reopen the terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Official support: macOS, Windows, common Linux distributions, and WSL. <strong>Alpine and other musl-based Linux distributions are not currently supported.</strong></p><p>If the command is missing: close and reopen the terminal, then run <code>mcode --version</code>. On Windows, a VS Code that was already open can keep a stale <code>PATH</code>; quit VS Code entirely (<a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>).</p><p>Update with <code>mcode update</code> or <code>/update</code> in the TUI.</p><h2 id="_4-sign-in" tabindex="-1">4. Sign in <a class="header-anchor" href="#_4-sign-in" aria-label="Permalink to &quot;4. Sign in&quot;">​</a></h2><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Sign in with your MiniMax account after launch (<a href="https://agent.minimax.io/docs/code/get-started/download" target="_blank" rel="noreferrer">Download</a>). For your own API key, see the <a href="./minimax-code-cookbook.html">cookbook</a>.</p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>Sign in before using MiniMax-hosted models or a Token Plan (<a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">quick-start</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>For a Global account:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --region</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span></span></code></pre></div><p>Sign-in finishes in the browser. Back in the TUI, run <code>/status</code>. Configure a custom provider or API key with <code>mcode provider</code>.</p><p>Mainland China accounts use <code>mcode login</code>. Global accounts use <code>mcode login --region global</code> (<a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>). Sign out with <code>mcode logout</code>.</p><p>WSL / SSH callback steps belong on the <a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>. The callback URL contains a temporary credential. Do not paste it into chat or a repo.</p><h2 id="_5-first-desktop-task" tabindex="-1">5. First desktop task <a class="header-anchor" href="#_5-first-desktop-task" aria-label="Permalink to &quot;5. First desktop task&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/code/get-started/first-task" target="_blank" rel="noreferrer">Create Your First Task</a>.</p><ol><li>Start from the home composer or create a new task.</li><li>Describe the outcome in natural language. Official examples include fixing a bug, building a page, writing a report, or analyzing files.</li><li>Attach files, pick a workspace, <code>@</code> project files, or <code>/</code> a skill.</li><li>Keep adding instructions while it runs. Answer permission prompts when they appear.</li></ol><p>Official writing tips: state the outcome, not only the process. For code, state the stack, constraints, and how you will accept the work. If the approach is unclear, ask it to plan first.</p><p>To edit an existing repo, attach a workspace first. Official text: after you choose a project directory, the agent can read files, run commands, produce artifacts, and report changes in that directory. Pick only the directory that belongs to the task (<a href="https://agent.minimax.io/docs/code/workflows/workspace" target="_blank" rel="noreferrer">Workspace</a>).</p><h2 id="_6-first-cli-task" tabindex="-1">6. First CLI task <a class="header-anchor" href="#_6-first-cli-task" aria-label="Permalink to &quot;6. First CLI task&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span></span></code></pre></div><p>Or submit on launch:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Inspect the failing tests in this project, fix them, and run the relevant tests to verify the changes&quot;</span></span></code></pre></div><p>On a new repo, generate project instructions (officially creates or updates <code>AGENTS.md</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Include the expected outcome, change boundaries, and validation method (<a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">quick-start</a>).</p><p>Resume:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span></span></code></pre></div><p>In the TUI, use <code>/sessions [query]</code>. The <a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a> says to pass a known session id to <code>mcode --session</code>.</p><p>Starter keys (same page):</p><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Send; extra messages queue while a task runs</td></tr><tr><td><code>Shift+Enter</code></td><td>New line</td></tr><tr><td><code>@</code></td><td>Reference a file or directory</td></tr><tr><td><code>Shift+Tab</code></td><td>Default ↔ Plan Mode</td></tr><tr><td><code>Alt+M</code></td><td>Ask, Auto, Full access</td></tr><tr><td><code>Esc</code></td><td>Close a panel or interrupt</td></tr></tbody></table><p>Starter slash commands: <code>/help</code>, <code>/status</code>, <code>/model</code>, <code>/sessions</code>, <code>/context</code>, <code>/compact</code>, <code>/new</code>, <code>/init</code>, <code>/quit</code>. Treat <code>/help</code> as the live list.</p><h2 id="_7-coding-mode-or-work-mode" tabindex="-1">7. Coding mode or Work mode <a class="header-anchor" href="#_7-coding-mode-or-work-mode" aria-label="Permalink to &quot;7. Coding mode or Work mode&quot;">​</a></h2><p>Desktop only. Official text: they &quot;use the same Agent capabilities&quot; with different UI and tool exposure (<a href="https://agent.minimax.io/docs/code/workflows/modes" target="_blank" rel="noreferrer">Modes</a>).</p><table tabindex="0"><thead><tr><th>Situation</th><th>Mode</th></tr></thead><tbody><tr><td>Read or edit a code repo</td><td>Coding</td></tr><tr><td>Need the terminal, browser, or file panels</td><td>Coding</td></tr><tr><td>You care about the deliverable, not the implementation</td><td>Work</td></tr><tr><td>Multi-step work with no local code</td><td>Work</td></tr></tbody></table><p>Coding: new features, bug fixes, tests, diffs, web / HTML debugging. Work: docs, research, spreadsheets, writing, office automation.</p><h2 id="_8-permissions" tabindex="-1">8. Permissions <a class="header-anchor" href="#_8-permissions" aria-label="Permalink to &quot;8. Permissions&quot;">​</a></h2><p>The desktop app confirms before it (<a href="https://agent.minimax.io/docs/code/workflows/permissions" target="_blank" rel="noreferrer">Permissions</a>):</p><ul><li>Reads files outside the workspace</li><li>Modifies or deletes files</li><li>Runs commands</li><li>Uses tools with external effects</li><li>Handles actions that arrived through Remote Control or IM</li></ul><p>Official advice: stay conservative on a new project; lower the prompt frequency for familiar low-risk repeats; keep a human in the loop for delete, overwrite, upload, and sending messages.</p><p>On the CLI, Plan Mode and permission mode are <strong>separate</strong> (<a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>):</p><ul><li>Plan Mode: execute the next message or plan first. <code>Shift+Tab</code> or <code>/plan</code>.</li><li>Permission mode: how tools are confirmed. <code>Alt+M</code> or <code>/permission</code> → Ask, Auto, Full access.</li></ul><p><code>mcode exec</code> accepts <code>--permission</code> with <code>ask</code>, <code>smart</code>, <code>full</code>, or <code>off</code> (<a href="https://agent.minimax.io/docs/cli/features" target="_blank" rel="noreferrer">features</a>). Do not merge the TUI names and the exec names into one enum.</p><h2 id="_9-next" tabindex="-1">9. Next <a class="header-anchor" href="#_9-next" aria-label="Permalink to &quot;9. Next&quot;">​</a></h2><ul><li>Split hard work: <a href="./minimax-code-cookbook.html">Cookbook · Agent Team</a></li><li>Scripts / CI: <code>mcode exec</code></li><li>Editors: <code>mcode acp</code> (official Zed snippet)</li><li>Lookup: <a href="./minimax-code-cheatsheet.html">cheatsheet</a></li></ul>`,64)])])}const f=t(o,[["render",n]]);export{g as __pageData,f as default};
